# Script to find unused images in Obsidian vault

$vaultPath = "C:\Users\cong.pi\Documents\obsidian-note"
$imageRefs = @()

# Scan all markdown files for image references
Write-Host "Scanning markdown files for image references..."
Get-ChildItem -Path $vaultPath -Filter "*.md" -Recurse | ForEach-Object {
    $content = Get-Content $_.FullName -Raw -ErrorAction SilentlyContinue
    if ($content) {
        # Obsidian style: ![[image.png]]
        $obsidianMatches = [regex]::Matches($content, '!\[\[([^\]]+\.(png|jpg|jpeg|gif|avif|webp|svg|bmp))\]\]')
        foreach ($match in $obsidianMatches) {
            $imagePath = $match.Groups[1].Value
            # Remove ./ prefix if present
            $imagePath = $imagePath -replace '^\.\/', ''
            $imageRefs += $imagePath
        }

        # Markdown style: ![](image.png)
        $mdMatches = [regex]::Matches($content, '!\[[^\]]*\]\(([^)]+\.(png|jpg|jpeg|gif|avif|webp|svg|bmp))\)')
        foreach ($match in $mdMatches) {
            $imagePath = $match.Groups[1].Value
            # Skip URLs
            if ($imagePath -notmatch '^https?://') {
                # Remove ./ prefix if present
                $imagePath = $imagePath -replace '^\.\/', ''
                $imageRefs += $imagePath
            }
        }
    }
}

# Get unique image references
$uniqueRefs = $imageRefs | Sort-Object -Unique
Write-Host "Found $($uniqueRefs.Count) unique image references"

# Save to file
$uniqueRefs | Out-File -FilePath "$vaultPath\referenced_images.txt" -Encoding UTF8

# Find all image files in vault root (excluding subdirectories)
Write-Host "`nScanning for image files in vault root..."
$rootImages = Get-ChildItem -Path $vaultPath -File | Where-Object {
    $_.Extension -match '\.(png|jpg|jpeg|gif|avif|webp|svg|bmp)$'
}

Write-Host "Found $($rootImages.Count) image files in vault root"

# Find unused images
$unusedImages = @()
foreach ($image in $rootImages) {
    $imageName = $image.Name
    $isReferenced = $false

    foreach ($ref in $uniqueRefs) {
        # Check if the reference matches this image
        if ($ref -eq $imageName -or $ref -like "*/$imageName" -or $ref -like "*\$imageName") {
            $isReferenced = $true
            break
        }
    }

    if (-not $isReferenced) {
        $unusedImages += $image
    }
}

Write-Host "`nFound $($unusedImages.Count) unused images in vault root"

# Save unused images list
$unusedImages | Select-Object Name, Length, LastWriteTime | Out-File -FilePath "$vaultPath\unused_images.txt" -Encoding UTF8

# Display results
Write-Host "`nUnused images:"
$unusedImages | ForEach-Object {
    Write-Host "  - $($_.Name) ($([math]::Round($_.Length/1KB, 2)) KB)"
}

Write-Host "`nTotal size: $([math]::Round(($unusedImages | Measure-Object -Property Length -Sum).Sum / 1MB, 2)) MB"

